const std = @import("std");
const algebra = @import("algebra.zig");

pub fn main(init: std.process.Init) !void {
    var buffer: [4096]u8 = undefined;
    var stdout = std.Io.File.stdout().writer(init.io, &buffer);
    inline for (.{ algebra.Cl3f, algebra.Cl3d, algebra.Cl4f, algebra.Cl4d, algebra.Pga3f, algebra.Pga3d, algebra.Pga4f, algebra.Pga4d, algebra.Cga3f, algebra.Cga3d, algebra.Cga4f, algebra.Cga4d }) |A| {
        var input = A.one();
        std.mem.doNotOptimizeAway(&input);
        const conjugate = input.conjugate().evenPart();
        const product = conjugate.geometricProduct(input);
        const inverse = input.inverseChecked();
        const static_inverse = A.one().inverseChecked();
        var residuals: usize = 0;
        for (product.coefficients()[1..]) |value| {
            if (value != 0) residuals += 1;
        }
        try stdout.interface.print("{s}: finite={} inverse={} static_inverse={} scalar={d} residuals={d}\n", .{ @typeName(A), input.isFinite(), inverse != null, static_inverse != null, product.scalarPart(), residuals });
    }
    try stdout.interface.flush();
}
